DROP TABLE IF EXISTS `admin_permissions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `admin_permissions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL COMMENT 'Authority / permission name',
  `code` varchar(255) DEFAULT NULL COMMENT 'Unique slug code for this permission group',
  `description` varchar(255) DEFAULT NULL COMMENT 'Permission description',
  `usage_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'active' COMMENT 'Usage status: active, inactive',
  `menu_permissions` json DEFAULT NULL COMMENT 'Per-menu permissions (view/register/edit/delete/approval)',
  `created_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `admin_permissions_code_unique` (`code`),
  KEY `admin_permissions_name_index` (`name`),
  KEY `admin_permissions_usage_status_index` (`usage_status`),
  KEY `admin_permissions_created_by_index` (`created_by`),
  CONSTRAINT `admin_permissions_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
