--
-- Table structure for table `customers`
--

DROP TABLE IF EXISTS `customers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `customers` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `branch_in_charge` bigint unsigned DEFAULT NULL COMMENT 'Foreign key referencing the codes table for branch assignment',
  `is_seomun_graphics_branch` tinyint(1) NOT NULL DEFAULT '0',
  `access_code` varchar(20) NOT NULL COMMENT 'Access code for the customer login',
  `api_key` varchar(255) DEFAULT NULL,
  `webhook_secret` varchar(255) DEFAULT NULL,
  `site_version` varchar(255) NOT NULL DEFAULT 'legacy' COMMENT 'System version: legacy, v2, v3',
  `company_name` varchar(255) NOT NULL COMMENT 'Customer company name',
  `business_registration_number` varchar(255) DEFAULT NULL COMMENT 'Business tax ID',
  `representative_name` varchar(255) DEFAULT NULL,
  `business_type` varchar(255) DEFAULT NULL,
  `business_items` varchar(255) DEFAULT NULL,
  `industry_type` varchar(255) DEFAULT NULL COMMENT '업종',
  `mro_customer_code` varchar(255) DEFAULT NULL COMMENT 'Internal MRO system code',
  `contact_name` varchar(255) DEFAULT NULL,
  `contact_position` varchar(255) DEFAULT NULL,
  `contact_phone` varchar(20) DEFAULT NULL,
  `contact_mobile` varchar(255) DEFAULT NULL,
  `contact_email` varchar(255) DEFAULT NULL,
  `tax_invoice_email` varchar(255) DEFAULT NULL COMMENT '전자세금계산서 이메일',
  `homepage_url` varchar(255) DEFAULT NULL COMMENT '홈페이지 URL',
  `business_registration_file` varchar(255) DEFAULT NULL COMMENT '사업자등록증 파일 경로',
  `contact_fax` varchar(255) DEFAULT NULL,
  `postcode` varchar(10) DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `detailed_address` varchar(255) DEFAULT NULL,
  `status` varchar(255) NOT NULL DEFAULT 'normal' COMMENT 'Status: normal, pending, inactive',
  `approval_status` varchar(255) NOT NULL DEFAULT 'pending' COMMENT 'pending, accepted, rejected',
  `approval_request_type` varchar(255) DEFAULT NULL COMMENT 'new_signup | information_modification | permission_change',
  `approved_at` timestamp NULL DEFAULT NULL,
  `approved_by` bigint unsigned DEFAULT NULL,
  `rejected_at` timestamp NULL DEFAULT NULL,
  `rejected_by` bigint unsigned DEFAULT NULL,
  `rejected_reason` text,
  `customer_skin` varchar(255) NOT NULL DEFAULT 'basic',
  `customer_header_title` varchar(255) DEFAULT NULL,
  `customer_footer_copyright` varchar(255) DEFAULT NULL,
  `customer_footer_contact_number_1` varchar(255) DEFAULT NULL,
  `customer_footer_contact_number_2` varchar(255) DEFAULT NULL,
  `logo_v3_common` varchar(255) DEFAULT NULL,
  `logo_v2_header` varchar(255) DEFAULT NULL,
  `logo_v2_login` varchar(255) DEFAULT NULL,
  `shipping_method` varchar(255) DEFAULT NULL,
  `shipping_fee_type` varchar(255) DEFAULT NULL,
  `shipping_fee_applied` varchar(255) NOT NULL COMMENT 'Logic for applying shipping fees',
  `shipping_fee` decimal(12,2) NOT NULL DEFAULT '0.00',
  `free_shipping_min_order_amount` int DEFAULT NULL,
  `postpaid_payment_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `prepaid_payment_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `prepaid_payment_methods` varchar(255) DEFAULT NULL COMMENT 'Comma separated methods',
  `main_menu` varchar(255) DEFAULT NULL,
  `order_menus` varchar(255) NOT NULL COMMENT 'Enabled order menu list',
  `other_menus` varchar(255) NOT NULL COMMENT 'Secondary menu list',
  `delivery_confirmation_step_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `order_history_retention_days` decimal(8,2) DEFAULT '7.00',
  `tcps_enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'TCPS integration status',
  `document_upload_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `signup_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `member_approval_required` tinyint(1) NOT NULL DEFAULT '0',
  `signup_approval_email_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `signup_approval_email` varchar(255) DEFAULT NULL,
  `signup_approval_sms_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `signup_approval_phone` varchar(255) DEFAULT NULL,
  `signup_approval_result_email_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `order_notification_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `order_notification_phone` varchar(255) DEFAULT NULL,
  `order_notification_email` varchar(255) DEFAULT NULL,
  `simple_order_sms_notification_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `simple_order_sms_notification_phone` varchar(255) DEFAULT NULL,
  `order_teams_notification_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `org_level_1_name` varchar(255) DEFAULT NULL,
  `org_level_2_name` varchar(255) DEFAULT NULL,
  `org_level_3_name` varchar(255) DEFAULT NULL,
  `sales_representative_name` varchar(255) DEFAULT NULL,
  `sales_representative_contact` varchar(255) DEFAULT NULL,
  `is_mro` tinyint(1) NOT NULL DEFAULT '0',
  `is_franchise` tinyint(1) NOT NULL DEFAULT '1',
  `is_partner` tinyint(1) NOT NULL DEFAULT '0',
  `commission_cloud_card` varchar(255) DEFAULT NULL,
  `commission_office_printing` varchar(255) DEFAULT NULL,
  `commission_pro_order` varchar(255) DEFAULT NULL,
  `commission_custom_product` varchar(255) DEFAULT NULL,
  `commission_promo_material` varchar(255) DEFAULT NULL,
  `commission_name_tag` varchar(255) DEFAULT NULL,
  `commission_large_format_print` varchar(255) DEFAULT NULL,
  `commission_file_order` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `customers_access_code_unique` (`access_code`),
  UNIQUE KEY `customers_api_key_unique` (`api_key`),
  UNIQUE KEY `customers_webhook_secret_unique` (`webhook_secret`),
  UNIQUE KEY `customers_business_registration_number_unique` (`business_registration_number`),
  KEY `customers_approved_by_foreign` (`approved_by`),
  KEY `customers_rejected_by_foreign` (`rejected_by`),
  KEY `customers_company_name_index` (`company_name`),
  KEY `customers_status_index` (`status`),
  KEY `customers_approval_status_index` (`approval_status`),
  KEY `customers_branch_in_charge_foreign` (`branch_in_charge`),
  CONSTRAINT `customers_approved_by_foreign` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `customers_branch_in_charge_foreign` FOREIGN KEY (`branch_in_charge`) REFERENCES `codes` (`id`) ON DELETE SET NULL,
  CONSTRAINT `customers_rejected_by_foreign` FOREIGN KEY (`rejected_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

