--
-- Table structure for table `design_groups`
--

DROP TABLE IF EXISTS `design_groups`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `design_groups` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `product_id` bigint unsigned DEFAULT NULL,
  `order_id` bigint unsigned DEFAULT NULL,
  `order_item_id` bigint unsigned DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `source_type` varchar(30) NOT NULL,
  `preview_image_path` varchar(255) DEFAULT NULL,
  `preview_pdf_url` varchar(255) DEFAULT NULL,
  `metadata` json DEFAULT NULL,
  `revised_file_path` varchar(255) DEFAULT NULL,
  `revised_file_name` varchar(255) DEFAULT NULL,
  `rejection_reason` text,
  `confirmation_requested_at` timestamp NULL DEFAULT NULL,
  `confirmed_at` timestamp NULL DEFAULT NULL,
  `rejected_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `size_option_id` bigint unsigned DEFAULT NULL,
  `width_mm` int DEFAULT NULL,
  `height_mm` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `design_groups_user_id_foreign` (`user_id`),
  KEY `design_groups_product_id_foreign` (`product_id`),
  KEY `design_groups_order_id_foreign` (`order_id`),
  KEY `design_groups_order_item_id_foreign` (`order_item_id`),
  KEY `design_groups_size_option_id_foreign` (`size_option_id`),
  CONSTRAINT `design_groups_order_id_foreign` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE SET NULL,
  CONSTRAINT `design_groups_order_item_id_foreign` FOREIGN KEY (`order_item_id`) REFERENCES `order_items` (`id`) ON DELETE SET NULL,
  CONSTRAINT `design_groups_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE SET NULL,
  CONSTRAINT `design_groups_size_option_id_foreign` FOREIGN KEY (`size_option_id`) REFERENCES `erp_size_options` (`id`) ON DELETE SET NULL,
  CONSTRAINT `design_groups_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=193 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

