DROP TABLE IF EXISTS `erp_size_options`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `erp_size_options` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL COMMENT 'Size name (e.g., A4, Business Card, Custom)',
  `cutting_width` decimal(12,2) NOT NULL,
  `cutting_height` decimal(12,2) NOT NULL,
  `working_width` decimal(12,2) NOT NULL,
  `working_height` decimal(12,2) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `created_by` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_size_option_unique` (`name`),
  KEY `erp_size_options_created_by_foreign` (`created_by`),
  CONSTRAINT `erp_size_options_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

