DROP TABLE IF EXISTS `home_sections`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `home_sections` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `type` varchar(50) NOT NULL COMMENT '섹션 타입 (Section Type): banner, popular_products, category_icons, recent_orders, notices, etc.',
  `title` varchar(255) DEFAULT NULL COMMENT '제목 (Title)',
  `subtitle` varchar(255) DEFAULT NULL COMMENT '부제목 (Subtitle)',
  `content` text COMMENT '내용 (Content) - JSON format for flexible data',
  `image` varchar(500) DEFAULT NULL COMMENT '이미지 URL (Image URL)',
  `link` varchar(500) DEFAULT NULL COMMENT '링크 (Link URL)',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '정렬 순서 (Sort Order)',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT '활성화 여부 (Active Status)',
  `starts_at` timestamp NULL DEFAULT NULL COMMENT '시작 시간 (Start Time)',
  `ends_at` timestamp NULL DEFAULT NULL COMMENT '종료 시간 (End Time)',
  `metadata` json DEFAULT NULL COMMENT '추가 메타데이터 (Additional Metadata)',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `home_sections_type_index` (`type`),
  KEY `home_sections_is_active_index` (`is_active`),
  KEY `home_sections_sort_order_index` (`sort_order`),
  KEY `home_sections_is_active_sort_order_index` (`is_active`,`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
