DROP TABLE IF EXISTS `notification_histories`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notification_histories` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `notification_template_id` bigint unsigned DEFAULT NULL,
  `notification_type` enum('email','notification_talk','sms') NOT NULL COMMENT 'Notification type',
  `recipient_name` varchar(255) DEFAULT NULL COMMENT 'Recipient name',
  `recipient_contact` varchar(255) DEFAULT NULL COMMENT 'Recipient email/phone',
  `message_title` varchar(255) DEFAULT NULL COMMENT 'Message title / subject',
  `message_content` text COMMENT 'Message content',
  `sending_result` enum('success','failure') NOT NULL COMMENT 'Sending result',
  `failure_reason` text COMMENT 'Failure reason (if any)',
  `sender_id` bigint unsigned DEFAULT NULL,
  `sent_at` timestamp NULL DEFAULT NULL COMMENT 'Sending date and time',
  `meta` json DEFAULT NULL COMMENT 'Additional metadata (payload, channel config snapshot, etc.)',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `notification_histories_notification_template_id_index` (`notification_template_id`),
  KEY `notification_histories_notification_type_index` (`notification_type`),
  KEY `notification_histories_recipient_name_index` (`recipient_name`),
  KEY `notification_histories_sending_result_index` (`sending_result`),
  KEY `notification_histories_sender_id_index` (`sender_id`),
  KEY `notification_histories_sent_at_index` (`sent_at`),
  CONSTRAINT `notification_histories_notification_template_id_foreign` FOREIGN KEY (`notification_template_id`) REFERENCES `notification_templates` (`id`) ON DELETE SET NULL,
  CONSTRAINT `notification_histories_sender_id_foreign` FOREIGN KEY (`sender_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

