--
-- Table structure for table `notification_templates`
--

DROP TABLE IF EXISTS `notification_templates`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notification_templates` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL COMMENT 'Template name',
  `template_number` varchar(100) DEFAULT NULL COMMENT 'External template number / code',
  `trigger_event` varchar(100) DEFAULT NULL COMMENT 'Event that triggers this template, e.g. membership_level_upgrade, order_placed',
  `channel_configs` json NOT NULL COMMENT 'Channel configurations (email, notification talk, SMS)',
  `usage_status` enum('enabled','disabled') NOT NULL DEFAULT 'enabled' COMMENT 'Usage status',
