--
-- Table structure for table `order_code_erp_option`
--

DROP TABLE IF EXISTS `order_code_erp_option`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_code_erp_option` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_code_id` bigint unsigned NOT NULL,
  `erp_option_id` bigint unsigned NOT NULL,
  `product_type_condition` varchar(255) DEFAULT NULL COMMENT 'Display condition based on product type (e.g., specific category or material)',
  `osrc_um` decimal(15,2) DEFAULT NULL COMMENT 'Per-product outsourcing unit price (overrides erp_options.osrc_um)',
  `osrc_um_min` decimal(15,2) DEFAULT NULL COMMENT 'Minimum threshold for per-product outsourcing unit price',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_order_code_erp_option_unique` (`order_code_id`,`erp_option_id`),
