--
-- Table structure for table `order_shipments`
--

DROP TABLE IF EXISTS `order_shipments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_shipments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned NOT NULL,
  `type` varchar(20) NOT NULL DEFAULT 'combined' COMMENT 'combined = 합배송, separate = 따로 배송',
  `status` varchar(30) NOT NULL DEFAULT 'pending' COMMENT 'pending, shipped, delivered',
  `tracking_number` varchar(100) DEFAULT NULL,
  `carrier_code` varchar(50) DEFAULT NULL COMMENT 'SweetTracker carrier code',
  `carrier_name` varchar(255) DEFAULT NULL,
  `shipping_method` varchar(255) DEFAULT NULL,
  `memo` text,
  `shipping_fee` decimal(10,2) NOT NULL DEFAULT '0.00',
  `shipping_name` varchar(100) DEFAULT NULL,
  `shipping_phone` varchar(30) DEFAULT NULL,
  `shipping_postcode` varchar(20) DEFAULT NULL,
  `shipping_address` varchar(255) DEFAULT NULL,
  `shipping_address_detail` varchar(255) DEFAULT NULL,
  `shipped_at` timestamp NULL DEFAULT NULL,
  `delivered_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `order_shipments_order_id_type_index` (`order_id`,`type`),
  CONSTRAINT `order_shipments_order_id_foreign` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=71 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

