--
-- Table structure for table `payment_transactions`
--

DROP TABLE IF EXISTS `payment_transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payment_transactions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned NOT NULL,
  `transaction_id` varchar(255) NOT NULL COMMENT 'Internal unique transaction ID',
  `pg_transaction_id` varchar(255) DEFAULT NULL COMMENT 'Transaction ID from Payment Gateway (PG)',
  `pg_name` varchar(100) DEFAULT NULL COMMENT 'Payment gateway provider (e.g., KG Inicis, Toss)',
  `payment_method` varchar(50) NOT NULL COMMENT 'Available: card, virtual_account, bank_transfer, toss, seomun_pay, paylater',
  `status` varchar(50) NOT NULL DEFAULT 'pending' COMMENT 'pending, processing, paid, failed, cancelled, refunded',
  `amount` decimal(15,2) NOT NULL,
  `currency` varchar(3) NOT NULL DEFAULT 'KRW',
  `card_name` varchar(255) DEFAULT NULL COMMENT 'Card issuer name',
  `card_number` varchar(255) DEFAULT NULL COMMENT 'Masked card number',
  `virtual_account_number` varchar(255) DEFAULT NULL,
  `virtual_account_bank` varchar(255) DEFAULT NULL,
  `virtual_account_expires_at` timestamp NULL DEFAULT NULL,
  `bank_account_holder` varchar(255) DEFAULT NULL,
  `pg_request` json DEFAULT NULL COMMENT 'Original request sent to PG',
  `pg_response` json DEFAULT NULL COMMENT 'Final response received from PG',
  `refund_reason` text,
  `paid_at` timestamp NULL DEFAULT NULL,
  `failed_at` timestamp NULL DEFAULT NULL,
  `refunded_at` timestamp NULL DEFAULT NULL,
  `metadata` json DEFAULT NULL,
  `tax_invoice_status` varchar(20) DEFAULT NULL COMMENT 'null=not applicable, pending=pending issue, issued=issued, deleted=archived',
  `tax_invoice_issued_at` timestamp NULL DEFAULT NULL,
  `cash_receipt_status` varchar(20) DEFAULT NULL COMMENT 'null=not applicable, pending=pending issue, issued=issued, deleted=archived',
  `cash_receipt_issued_at` timestamp NULL DEFAULT NULL,
  `receipt_notes` text,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `payment_transactions_transaction_id_unique` (`transaction_id`),
  KEY `payment_transactions_order_id_status_index` (`order_id`,`status`),
  KEY `payment_transactions_pg_transaction_id_index` (`pg_transaction_id`),
  CONSTRAINT `payment_transactions_order_id_foreign` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=92 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
