--
-- Table structure for table `product_specifications`
--

DROP TABLE IF EXISTS `product_specifications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_specifications` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `product_id` bigint unsigned NOT NULL,
  `bleed_width` decimal(10,2) DEFAULT NULL,
  `bleed_height` decimal(10,2) DEFAULT NULL,
  `safe_width` decimal(10,2) DEFAULT NULL,
  `safe_height` decimal(10,2) DEFAULT NULL,
  `size_width_mm` decimal(10,2) DEFAULT NULL,
  `size_height_mm` decimal(10,2) DEFAULT NULL,
  `size_unit` varchar(10) NOT NULL DEFAULT 'mm',
  `paper_type` varchar(100) DEFAULT NULL,
  `paper_weight_gsm` smallint unsigned DEFAULT NULL,
  `production_time_days` smallint unsigned DEFAULT NULL,
  `notes` text,
  `dieline_enabled` tinyint(1) NOT NULL DEFAULT '0' COMMENT '칼선 다운로드 가능 여부 (Dieline Download Available)',
  `dieline_margin_mm` decimal(5,2) NOT NULL DEFAULT '2.00' COMMENT '칼선 여백 (Dieline margin beyond trim size, mm)',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `product_specifications_product_id_unique` (`product_id`),
  CONSTRAINT `product_specifications_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=34 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

