DROP TABLE IF EXISTS `user_admin_permissions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_admin_permissions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `admin_permission_id` bigint unsigned NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'active' COMMENT 'Status: active, inactive',
  `grant_date` date NOT NULL COMMENT 'Date when permission was granted',
  `created_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_admin_permissions_user_id_admin_permission_id_unique` (`user_id`,`admin_permission_id`),
  KEY `user_admin_permissions_user_id_index` (`user_id`),
  KEY `user_admin_permissions_admin_permission_id_index` (`admin_permission_id`),
  KEY `user_admin_permissions_status_index` (`status`),
  KEY `user_admin_permissions_grant_date_index` (`grant_date`),
  KEY `user_admin_permissions_created_by_index` (`created_by`),
  CONSTRAINT `user_admin_permissions_admin_permission_id_foreign` FOREIGN KEY (`admin_permission_id`) REFERENCES `admin_permissions` (`id`) ON DELETE CASCADE,
  CONSTRAINT `user_admin_permissions_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `user_admin_permissions_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
