--
-- Table structure for table `verification_codes`
--

DROP TABLE IF EXISTS `verification_codes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `verification_codes` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `identifier` varchar(255) NOT NULL COMMENT '이메일 또는 핸드폰 번호 (Email or Mobile Phone)',
  `type` enum('email','mobile') NOT NULL COMMENT '인증 타입 (Verification Type)',
  `code` varchar(10) NOT NULL COMMENT '인증번호 (Verification Code)',
  `purpose` enum('find_username','reset_password','register','find_id','change_phone','worker_verify') NOT NULL DEFAULT 'find_username',
  `attempts` int NOT NULL DEFAULT '0' COMMENT '시도 횟수 (Attempt Count)',
  `max_attempts` int NOT NULL DEFAULT '5' COMMENT '최대 시도 횟수 (Max Attempts)',
  `expires_at` timestamp NOT NULL COMMENT '만료 시간 (Expiration Time)',
  `verified_at` timestamp NULL DEFAULT NULL COMMENT '인증 완료 시간 (Verified At)',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `verification_codes_identifier_type_purpose_index` (`identifier`,`type`,`purpose`),
  KEY `verification_codes_code_index` (`code`),
  KEY `verification_codes_expires_at_index` (`expires_at`)
) ENGINE=InnoDB AUTO_INCREMENT=143 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

